//! Cargo-driven `sample.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is three-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "Entry", None),
        "x86_64" => ("x86_64-pc-windows-gnu", "Entry", Some(0x5000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "Entry", None),
        o => panic!("three-cargo: unsupported arch {o}"),
    };

    // The arches link different subsystem versions, as cmake's links did.
    let subsystem = match arch.as_str() {
        "x86" => "i386",
        "x86_64" => "amd64",
        "aarch64" => "arm64",
        _ => unreachable!(),
    };

    let static_libs: &[&str] = match arch.as_str() {
        "x86" => &["early"],
        "x86_64" => &["early"],
        "aarch64" => &["early"],
        _ => unreachable!(),
    };

    let late_libs: &[&str] = match arch.as_str() {
        "x86" => &["late"],
        "x86_64" => &["late"],
        "aarch64" => &["late"],
        _ => unreachable!(),
    };

    // target_link_options(LINKER:--require-defined=...): defined up front, so the
    // body's definition wins over an import thunk of the same name.
    let require_defined: &[&str] = match arch.as_str() {
        "x86" => &["-Wl,--require-defined=Sym", "-Wl,--require-defined=Other"],
        "x86_64" => &["-Wl,--require-defined=Sym", "-Wl,--require-defined=Other"],
        "aarch64" => &["-Wl,--require-defined=Sym", "-Wl,--require-defined=Other"],
        _ => unreachable!(),
    };

    // cmake built the body with these RUSTFLAGS (its rust_staticlib_variant ENV).
    let body_rustflags = match arch.as_str() {
        "x86" => Some("-C sse"),
        _ => None,
    };
    let mut link = Linker::new(target_json);
    if let Some(flags) = body_rustflags {
        link = link.rust_build_rustflags(flags);
    }
    link
        .rust_lib("three-rust", &["feature"], false)
        .c_from_compile_db(
            "3sample_shims",
            match arch.as_str() {
                "x86" => &["base.c", "i386.c"],
                "x86_64" => &["base.c", "amd64.c"],
                "aarch64" => &["base.c", "arm64.c"],
                _ => unreachable!(),
            },
        )
        .delay_import_lib("two.spec", "two.dll", "two")
        .import_lib("one.spec", "one.dll", "one")
        // cmake-built static libraries, reused until each has a cargo home.
        .static_libs(static_libs)
        // ...and those cmake linked after the body, in the same order.
        .static_libs_after_body(late_libs)
        .link_args(require_defined)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: Some(subsystem.into()),
        });
}

