//! Cargo-driven `sample.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is sample-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "Entry", Some(0x1234u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "Entry", Some(0x1234u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "Entry", Some(0x1234u64)),
        o => panic!("sample-cargo: unsupported arch {o}"),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &["-Ishared"];
    let rc_flags: &[&str] = match arch.as_str() {
        "x86" => &["-Di386"],
        "x86_64" => &["-Damd64"],
        "aarch64" => &["-Darm64"],
        _ => unreachable!(),
    };
    let rc_defines: &[&str] = &["FOO"];

    Linker::new(target_json)
        .rust_staticlib("sample-rust")
        .rc("path/demo.rc", rc_includes, rc_flags, rc_defines)
        .import_lib("one.spec", "one.dll", "one")
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}

