//! Cargo-driven `sample.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is sample-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "Entry", 0x1234u64),
        "x86_64" => ("x86_64-pc-windows-gnu", "Entry", 0x1234u64),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "Entry", 0x1234u64),
        o => panic!("sample-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["body", "import:one"],
        "x86_64" => &["body", "import:one"],
        "aarch64" => &["body", "import:one"],
        _ => unreachable!(),
    };

    Linker::new(target_json)
        .rust_staticlib("sample-rust")
        .rust_user_target()
        .spec2def("k.spec", "k.sys")
        .spec_stubs()
        .import_lib("one.spec", "one.dll", "one")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        // cmake's kernel-mode links keep every section.
        .keep_all_sections()
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .stack_reserve(4096)
        .link(ModuleKind::KernelDll {
            entry: entry.into(),
            image_base,
        });
}

