//! Cargo-driven `sample.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The module is C, compiled and linked by reactos-link: there is no Rust body.

use reactos_link::{Linker, ModuleKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "Entry"),
        "x86_64" => ("x86_64-pc-windows-gnu", "Entry"),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "Entry"),
        o => panic!("sample-cargo: unsupported arch {o}"),
    };

    Linker::new(target_json)
        .c_from_compile_db("sample_shims", &["a.c"])
        .whole_c_objects("sample_shims")
        .import_lib("one.spec", "one.dll", "one")
        .link(ModuleKind::Win32Exe {
            entry: entry.into(),
            subsystem: "console".into(),
        });
}

